content.content:
$auf = $null[cite: 1]
try { $auf = (Resolve-DnsName $Server -EA Stop | Where-Object {$_.IPAddress}).IPAddress } catch {}[cite: 1]

if ($auf) {
    Show-Status "DNS RESOLVE" "$Server -> $auf" "Green"[cite: 1]
} elseif ($hoch) {
    $h = "$env:WINDIR\System32\drivers\etc\hosts"[cite: 1]
    if (-not (Select-String -Path $h -Pattern 'bmd-app' -Quiet -EA SilentlyContinue)) {[cite: 1]
        Add-Content $h @('','# BMD-Insel, bis DHCP die DCs als DNS ausgibt',"$Ip    BMD-APP    $Server","$IpSql    BMD-SQL    bmd-sql.bmd.oekovolt.at") -Encoding Default[cite: 1]
        Show-Status "HOSTS FILE" "Eintrag erfolgreich hinzugefügt." "Yellow"[cite: 1]
    } else {
        Show-Status "HOSTS FILE" "Eintrag bereits vorhanden." "DarkGray"
    }
} else {
    Show-Status "WARNUNG" "Namensauflösung fehlt - Admin-Rechte erforderlich!" "Red"[cite: 1]
}

# ------------------------------------------------------------------------------
# SCHRITT 2: NETZWERKLAN-VERBINDUNG
# ------------------------------------------------------------------------------
Show-Step "2" "Verbindung zum BMD-Server herstellen"

Write-Host "  Authentifizierung läuft automatisch für $Konto..." -ForegroundColor DarkGray

Remove-SmbMapping -RemotePath $Pgm -Force -EA SilentlyContinue[cite: 1]
Remove-SmbMapping -RemotePath $Daten -Force -EA SilentlyContinue[cite: 1]

$verbindungErfolgreich = $true

foreach ($freigabe in @($Pgm, $Daten)) {[cite: 1]
    try {
        New-SmbMapping -RemotePath $freigabe -UserName $Konto -Password $Passwort -EA Stop | Out-Null[cite: 1]
        Show-Status "VERBUNDEN" $freigabe "Green"[cite: 1]
    } catch {
        Show-Status "FEHLER" "Verbindung fehlgeschlagen: $freigabe" "Red"[cite: 1]
        $verbindungErfolgreich = $false
    }
}

if (-not $verbindungErfolgreich) {
    Write-Host ""
    Write-Host "  [!] FEHLER: Authentifizierung fehlgeschlagen." -ForegroundColor Red
    Write-Host "      Bitte Passwort im Skript oder Netzwerk-Status prüfen." -ForegroundColor Yellow
    Write-Host ""
    exit
}

# ------------------------------------------------------------------------------
# SCHRITT 3: DESKTOP-VERKNÜPFUNG ERSTELLEN
# ------------------------------------------------------------------------------
Show-Step "3" "Verknüpfungen konfigurieren"

$desk = if ($hoch) { "$env:PUBLIC\Desktop" } else { [Environment]::GetFolderPath('Desktop') }[cite: 1]
$lnkPath = "$desk\BMD NTCS.lnk"[cite: 1]

if (Test-Path ([Environment]::GetFolderPath('Desktop') + '\BMDNetClient.lnk')) {[cite: 1]
    Show-Status "VERKNÜPFUNG" "BMD-Standardverknüpfung vorhanden." "Green"[cite: 1]
} else {
    try {
        $l = (New-Object -ComObject WScript.Shell).CreateShortcut($lnkPath)[cite: 1]
        $l.TargetPath = $Exe[cite: 1]
        $l.Description = 'BMD NTCS - Ökovolt Solartechnik'[cite: 1]
        $l.Save()[cite: 1]
        Show-Status "ERSTELLT" $lnkPath "Green"[cite: 1]
    } catch {
        Show-Status "FEHLER" "Verknüpfung konnte nicht erstellt werden." "Red"
    }
}

# ------------------------------------------------------------------------------
# SCHRITT 4: ABSCHLUSS & ANWENDUNGSSTART
# ------------------------------------------------------------------------------
Show-Step "4" "Einrichtung abgeschlossen"

if ($hoch) {
    Write-Host "  Starte Erstinstallation..." -ForegroundColor Cyan[cite: 1]
    Start-Process $Exe[cite: 1]
    Write-Host ""
    Write-Host "  [HINWEIS FOR ADMINS]" -ForegroundColor Yellow
    Write-Host "  Nach der Erstinstallation das Skript einmal OHNE Admin-Rechte" -ForegroundColor White[cite: 1]
    Write-Host "  für den jeweiligen Anwender ausführen!" -ForegroundColor White[cite: 1]
} else {
    Write-Host "  [SUCCESS] Einrichtung erfolgreich abgeschlossen!" -ForegroundColor Green[cite: 1]
    Write-Host "            BMD NTCS ist startbereit." -ForegroundColor White[cite: 1]
}

Write-Host ""
Write-Host "=======================================================================" -ForegroundColor Cyan

